def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The uniform 3x3 colored squares are the line sources.
    sources = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[y][x] == color for y in range(r, r + 3) for x in range(c, c + 3)):
                sources.append((r + 1, c + 1, color))
    rows, cols = {}, {}
    for r, c, color in sources:
        rows[r] = color
        cols[c] = color
    for r, color in rows.items():
        for c in range(w):
            out[r][c] = color
    for c, color in cols.items():
        for r in range(h):
            out[r][c] = color
    # At crossings between lines from different squares, the colors cancel.
    for r, hr_color in rows.items():
        for c, vc_color in cols.items():
            if hr_color != vc_color:
                out[r][c] = 0
    return out
